-- Options.lua
L["While you're flagged for PvP (not in dungeons or raids, nor on flights), and in battlegrounds and arenas."] = "Mentre hai il PvP attivo (non nelle spedizioni o incursioni, né in volo), e nei campi di battaglia e nelle arene."
